ALL_ROUTES.forEach(s=>{const photos=SPOT_PHOTOS[s.name]||{},seen={};[...s.days.flatMap(d=>d.stops),...(s.extras||[]),...(s.further||[])].forEach(p=>{if(photos[p.name]){const index=seen[p.name]||0;p.photo=photos[p.name][Math.min(index,photos[p.name].length-1)];seen[p.name]=index+1}});if(s.photo){const p=Object.values(photos).flat().find(p=>p.source===s.photo.source);if(p)s.photo=p;}});
